        lastKeys,
      );
      return r;
    },
    greetingReturning: (name, store, totalOrders) => {
      const r = pickAvoidRepeat(
        'greetingReturning',
        [
          `¡Qué bueno verte otra vez, *${name}*! Ya llevas *${totalOrders}* pedidos con *${store}* 🙌`,
          `*${name}*, gracias por confiar en *${store}* otra vez.`,
